import React, { useState, useEffect } from 'react';
import './Aiiot.css';

// Feather Icons Replacement Component
const FeatherIcon = ({ name, className = "" }) => {
    return <i data-feather={name} className={className}></i>;
};

// Carousel Images
const CAROUSEL_IMAGES = [
    { src: "/carousel-images/aiiot1.jpg", alt: "AI-IoT Innovation Technology" },
    { src: "/carousel-images/aiiot2.jpeg", alt: "Research Laboratory" },
   { src: "/carousel-images/aiiot3.jpg", alt: "Research Laboratory" },
   { src: "/carousel-images/aiiot4.jpg", alt: "Research Laboratory" },
];

// Project Data
const PROJECT_DATA = [
    { 
        title: "AI Hardware Design", 
        description: "Advanced neural network hardware integration",
        link: "#",
        icon: "trending-up"
    },
    { 
        title: "IoT Connectivity", 
        description: "Next-generation sensor network protocols",
        link: "#", 
        icon: "settings"
    }
];

// Services Data
const SERVICES_DATA = [
    {
        title: "AI Research",
        description: "Cutting-edge artificial intelligence research and development",
        icon: "cpu"
    },
    {
        title: "IoT Solutions",
        description: "Innovative Internet of Things integration and consulting",
        icon: "layers"
    },
    {
        title: "Hardware Design",
        description: "Advanced electronics and hardware prototyping",
        icon: "grid"
    }
];

// Faculty Data (expand this with all 9 faculty members)
const FACULTY_DATA = [
    {
        name: "Dr. Ajay Kumar",
        role: "Principal Investigator",
        image: "/faculties/ajay.jpeg",
        description: "Dr. Ajay Kumar is an Associate Professor at ASIET with a PhD in Electronics and Communication Engineering. His research interests include IoT and Wireless Sensor Networks.",
        profileLink: "https://www.adishankara.ac.in/department/faculty/25",
        linkedin: "#",
        twitter: "#"
    },
    {
        name: "Mr. Albins Paul",
        role: "Co-Investigator",
        image: "/faculties/albins.jpg",
        description: "Assistant Professor at ASIET's ECE Department, specializing in Microwave & Television Engineering.",
        profileLink: "#",
        linkedin: "#",
        twitter: "#"
    },
    {
        name: "Prof. P.V. Rajaraman",
        role: "Co-Investigator",
        image: "/faculties/albins.jpg", // Note: This seems to be a duplicate image
        description: "Assistant Professor, CTO, and Head of the AI Department at ASIET. He specializes in NLP and XAI, has multiple publications, and is currently pursuing his Ph.D.",
        profileLink: "#",
        linkedin: "#",
        twitter: "#"
    },
    // Add remaining 6 faculty members here
    // Example placeholder:
    {
        name: "Dr. Faculty Name",
        role: "Department Role",
        image: "/faculties/placeholder.jpg",
        description: "Faculty description goes here.",
        profileLink: "#",
        linkedin: "#",
        twitter: "#"
    }
    // ... repeat for total of 9 faculty members
];
// Team Members Data
const FacultyCard = ({ faculty }) => {
    const handleImageError = (e) => {
        e.target.onerror = null;
        e.target.src = 'https://placehold.co/128x128/e0e0e0/000000?text=Faculty';
    };

    return (
        <div className="text-center bg-white p-6 rounded-xl shadow-md border border-slate-200 transform transition duration-300 hover:-translate-y-2 hover:shadow-xl reveal-on-scroll">
            <a href={faculty.profileLink} target="_blank" rel="noopener noreferrer" className="block">
                <img 
                    className="w-32 h-32 mx-auto rounded-full mb-4 object-cover shadow-lg" 
                    src={faculty.image} 
                    alt={`Photo of ${faculty.name}`} 
                    loading="lazy" 
                    width="128" 
                    height="128"
                    onError={handleImageError}
                />
            </a>
            <a 
                href={faculty.profileLink} 
                target="_blank" 
                rel="noopener noreferrer" 
                className="hover:text-blue-800 transition duration-300"
            >
                <h4 className="text-xl font-bold text-blue-700">{faculty.name}</h4>
            </a>
            <p className="text-slate-500 font-medium mb-2">{faculty.role}</p>
            <p className="text-slate-600 text-sm mb-4">{faculty.description}</p>
            <div className="flex justify-center space-x-4">
                <a 
                    href={faculty.linkedin} 
                    target="_blank" 
                    rel="noopener noreferrer" 
                    className="text-slate-400 hover:text-blue-500" 
                    aria-label="LinkedIn"
                >
                    <FeatherIcon name="linkedin" />
                </a>
                <a 
                    href={faculty.twitter} 
                    target="_blank" 
                    rel="noopener noreferrer" 
                    className="text-slate-400 hover:text-blue-500" 
                    aria-label="Twitter"
                >
                    <FeatherIcon name="twitter" />
                </a>
            </div>
        </div>
    );
};



// Research Domains
const RESEARCH_DOMAINS = [
    "Artificial Intelligence",
    "Internet of Things",
    "Hardware Design",
    "Machine Learning",
    "Edge Computing",
    "Sensor Networks"
];

// Hero Section Component
export const HeroSection = () => {
    const [currentImageIndex, setCurrentImageIndex] = useState(0);

    useEffect(() => {
        const interval = setInterval(() => {
            setCurrentImageIndex((prevIndex) => 
                (prevIndex + 1) % CAROUSEL_IMAGES.length
            );
        }, 4000);

        return () => clearInterval(interval);
    }, []);

    return (
        <section id="hero" className="aiiot-hero-section">
            <div className="aiiot-hero-content">
                <h1 className="aiiot-hero-title">
                    <span className="block text-xl mb-2">Sponsored by</span>
                    <span className="text-blue-600">Ministry of Electronics and Information Technology</span>
                </h1>
                <p className="aiiot-hero-subtitle">
                    The Center for AI IoT Innovation is a facility focused on the integration of electronics hardware design with artificial intelligence (AI) and explainable AI (XAI).
                </p>
                <div className="aiiot-hero-cta">
                    <a href="/projects" className="aiiot-hero-cta-button aiiot-hero-cta-primary">
                        Explore Projects
                    </a>
                    <a href="/about" className="aiiot-hero-cta-button aiiot-hero-cta-secondary">
                        Learn More
                    </a>
                </div>

                <div className="aiiot-hero-carousel">
                    <img 
                        src={CAROUSEL_IMAGES[currentImageIndex].src} 
                        alt={CAROUSEL_IMAGES[currentImageIndex].alt} 
                        className="aiiot-hero-carousel-image"
                    />
                    <div className="aiiot-hero-carousel-indicators">
                        {CAROUSEL_IMAGES.map((_, index) => (
                            <div 
                                key={index} 
                                className={`aiiot-hero-carousel-indicator ${
                                    index === currentImageIndex 
                                    ? 'aiiot-hero-carousel-indicator-active' 
                                    : 'aiiot-hero-carousel-indicator-inactive'
                                }`}
                                onClick={() => setCurrentImageIndex(index)}
                            ></div>
                        ))}
                    </div>
                </div>
            </div>
        </section>
    );
};

// About Section Component
export const AboutSection = () => {
    return (
        <section id="about" className="aiiot-about-section">
            <div className="aiiot-about-content">
                <div className="aiiot-about-image">
                    <img 
                        src="/carousel-images/aiiot3.jpeg" 
                        alt="Collaborative team working in a modern tech lab" 
                        loading="lazy" 
                    />
                </div>
                <div className="aiiot-about-text">
                    <h2 className="aiiot-about-title">Our Mission</h2>
                    <p className="aiiot-about-description">
                        We bridge the gap between advanced electronics, artificial intelligence, and internet of things technologies to create innovative solutions that transform industries.
                    </p>
                    <div className="aiiot-about-projects">
                        {PROJECT_DATA.map((project, index) => (
                            <div key={index} className="aiiot-about-project">
                                <FeatherIcon name={project.icon} className="aiiot-about-project-icon" />
                                <div className="aiiot-about-project-details">
                                    <h4 className="aiiot-about-project-title">{project.title}</h4>
                                    <p className="aiiot-about-project-description">{project.description}</p>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </section>
    );
};

// Services Section Component
export const ServicesSection = () => {
    return (
        <section id="services" className="services-section bg-gray-100 py-16">
            <div className="container mx-auto px-4">
                <div className="text-center mb-12">
                    <h2 className="text-3xl font-bold text-slate-800 mb-4">Our Services</h2>
                    <p className="text-slate-600 max-w-2xl mx-auto">
                        Comprehensive solutions at the intersection of AI, IoT, and cutting-edge technology
                    </p>
                </div>
                <div className="grid md:grid-cols-3 gap-8">
                    {SERVICES_DATA.map((service, index) => (
                        <div key={index} className="service-card bg-white p-6 rounded-lg shadow-md text-center">
                            <FeatherIcon name={service.icon} className="mx-auto mb-4 text-blue-600 text-4xl" />
                            <h3 className="text-xl font-semibold mb-3">{service.title}</h3>
                            <p className="text-slate-600">{service.description}</p>
                        </div>
                    ))}
                </div>
            </div>
        </section>
    );
};

// Team Section Component
export const FacultySection = () => {
    return (
        <section id="faculty" className="faculty-section py-16 bg-gray-50">
            <div className="container mx-auto px-4">
                <div className="text-center mb-12">
                    <h2 className="text-3xl font-bold text-slate-800 mb-4">Our Faculty</h2>
                    <p className="text-slate-600 max-w-2xl mx-auto">
                        Meet the experts driving innovation and research
                    </p>
                </div>
                <div className="grid md:grid-cols-3 gap-8">
                    {FACULTY_DATA.map((faculty, index) => (
                        <FacultyCard key={index} faculty={faculty} />
                    ))}
                </div>
            </div>
        </section>
    );
};
// Research Domains Section
export const ResearchSection = () => {
    return (
        <section id="research" className="research-section bg-gray-50 py-16">
            <div className="container mx-auto px-4">
                <div className="text-center mb-12">
                    <h2 className="text-3xl font-bold text-slate-800 mb-4">Research Domains</h2>
                    <p className="text-slate-600 max-w-2xl mx-auto">
                        Our comprehensive research spans multiple cutting-edge technological domains
                    </p>
                </div>
                <div className="flex flex-wrap justify-center gap-4">
                    {RESEARCH_DOMAINS.map((domain, index) => (
                        <span 
                            key={index} 
                            className="bg-blue-100 text-blue-800 px-4 py-2 rounded-full text-sm font-medium"
                        >
                            {domain}
                        </span>
                    ))}
                </div>
            </div>
        </section>
    );
};

// Footer Component
export const Footer = () => {
    return (
        <footer className="bg-slate-900 text-white py-12">
            <div className="container mx-auto px-4 grid md:grid-cols-4 gap-8">
                <div>
                    <h3 className="text-xl font-bold mb-4">AI-IoT Innovation Center</h3>
                    <p className="text-slate-400">
                        Bridging technology and innovation for a smarter future
                    </p>
                </div>
                <div>
                    <h4 className="font-semibold mb-3">Quick Links</h4>
                    <ul className="space-y-2">
                        <li><a href="#hero" className="text-slate-400 hover:text-white">Home</a></li>
                        <li><a href="#about" className="text-slate-400 hover:text-white">About</a></li>
                        <li><a href="#services" className="text-slate-400 hover:text-white">Services</a></li>
                        <li><a href="#team" className="text-slate-400 hover:text-white">Team</a></li>
                    </ul>
                </div>
                <div>
                    <h4 className="font-semibold mb-3">Contact</h4>
                    <ul className="space-y-2">
                        <li>Email: contact@aiiot.gov.in</li>
                        <li>Phone: +91 (011) 2345-6789</li>
                        <li>Address: Tech Campus, New Delhi, India</li>
                    </ul>
                </div>
                <div>
                    <h4 className="font-semibold mb-3">Follow Us</h4>
                    <div className="flex space-x-4">
                        <a href="#" className="text-slate-400 hover:text-white">
                            <FeatherIcon name="twitter" />
                        </a>
                        <a href="#" className="text-slate-400 hover:text-white">
                            <FeatherIcon name="linkedin" />
                        </a>
                        <a href="#" className="text-slate-400 hover:text-white">
                            <FeatherIcon name="github" />
                        </a>
                    </div>
                </div>
            </div>
            <div className="text-center mt-8 border-t border-slate-700 pt-4">
                <p className="text-slate-500">
                    © 2025 AI-IoT Innovation Center. All Rights Reserved.
                </p>
            </div>
        </footer>
    );
};

// AI-IoT Innovation Center Page Component
export const AiIotInnovationCenter = () => {
    return (
        <div className="min-h-screen flex flex-col">
            <main className="flex-grow">
                <HeroSection />
                <AboutSection />
                <ServicesSection />
                <FacultySection />  
                <ResearchSection />
            </main>
            <Footer />
        </div>
    );
};

export default AiIotInnovationCenter;
